window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2dbe784b7eb59f49"]={"versions": [{"id": "FIG-2dbe784b7eb59f49", "releases": ["R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Ablaufdiagramm (SPEM/UML-Aktivitätsorientiert) zur Spezifikation und Konfiguration von Prozessen in der AUTOSAR Adaptive Platform. Das Diagramm modelliert den methodischen Workflow zur Überführung einer ausführbaren Anwendung (<code>Executable Application</code>) in instanziierte Prozesse (<code>Process</code>) sowie deren maschinenspezifische Start- und Ausführungsabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Aktivitäten (horizontale Prozesspfeile):</li>\n<li><code>Define Process</code>: Erzeugt Prozessinstanzen basierend auf der ausführbaren Anwendung.</li>\n<li><code>Define Startup Configuration</code>: Definiert die zustands- und modenabhängigen Startparameter für den Prozess auf einer konkreten Maschine.</li>\n<li><code>Define Execution Dependencies</code>: Definiert modenabhängige Ausführungs- und Startreihenfolgen bzw. Abhängigkeiten zwischen Prozessen auf einer Maschine.</li>\n<li>Arbeits- und Konfigurationsartefakte:</li>\n<li><code>Executable Application</code> (Briefumschlag-Symbol mit Port-Leiste links): Ausführbares Binär-/Software-Artefakt (Kardinalität <code>1</code> als Eingang).</li>\n<li><code>Process</code> (Dokument-Symbol): Manifest-Beschreibungsartefakt für den instanziierten Prozess (Kardinalität <code>1..*</code> als Ausgang von <code>Define Process</code>; Kardinalität <code>1</code> jeweils als Eingang für Folgeaktivitäten).</li>\n<li><code>Machine Manifest</code> (Briefumschlag-Symbol mit Port-Leiste links): Maschinenkonfiguration/Plattform-Manifest (Kardinalität <code>1</code> jeweils als Eingang für <code>Define Startup Configuration</code> und <code>Define Execution Dependencies</code>).</li>\n<li><code>Mode-dependent ...</code> (Dokument-Symbol am unteren Rand): Modenabhängige Prozesskonfigurationen (Ausgang mit Kardinalität <code>1..*</code> von beiden Folgeaktivitäten).</li>\n<li>Kontroll- und Datenflüsse:</li>\n<li>Stereotypisierte gerichtete Kanten («input», «output») mit expliziten Kardinalitäten verbinden Artefakte und Aktivitäten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Workflow beginnt mit der Übergabe einer <code>Executable Application</code> («input», 1) an die Aktivität <code>Define Process</code>.</li>\n<li><code>Define Process</code> erzeugt daraus mindestens eine Prozessdefinition <code>Process</code> («output», 1..*).</li>\n<li>Die resultierende <code>Process</code>-Spezifikation wird zusammen mit dem <code>Machine Manifest</code> parallel in zwei Folgeaktivitäten eingespeist:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eingang in <code>Define Startup Configuration</code> («input», 1 für <code>Process</code> und 1 für <code>Machine Manifest</code>).</li>\n<li>Eingang in <code>Define Execution Dependencies</code> («input», 1 für <code>Process</code> und 1 für <code>Machine Manifest</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Beide Aktivitäten generieren modenabhängige Prozess- und Ausführungsbeschreibungen (<code>Mode-dependent ...</code>, «output», jeweils 1..*).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den Entwicklungsprozess der AUTOSAR Adaptive Platform: Ein Prozess ist eine Instanziierung einer <code>Executable Application</code> auf einer Maschine. Für die vollständige Deployment-Konfiguration muss ein Prozess sowohl über Startkonfigurationen als auch über Ausführungsabhängigkeiten im Kontext des <code>Machine Manifest</code> verfügen. Werkzeuge für den Adaptive-Workflow müssen diese Artefakt-Abhängigkeiten und Kardinalitäten validieren.</p>"}, {"id": "FIG-4747b509285e17c5", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Ablaufdiagramm (SPEM/UML-Aktivitätsorientiert) zur Spezifikation und Konfiguration von Prozessen in der AUTOSAR Adaptive Platform. Das Diagramm modelliert den methodischen Workflow zur Überführung einer ausführbaren Anwendung (<code>Executable Application</code>) in instanziierte Prozesse (<code>Process</code>) sowie deren maschinenspezifische Start- und Ausführungsabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Aktivitäten (horizontale Prozesspfeile):</li>\n<li><code>Define Process</code>: Erzeugt Prozessinstanzen basierend auf der ausführbaren Anwendung.</li>\n<li><code>Associate Process with ProcessDesign</code>: Verknüpft die Prozessinstanz mit dem zugehörigen Entwurfsmodell (<code>Process Design</code>).</li>\n<li><code>Define Startup Configuration</code>: Definiert die zustands- und modenabhängigen Startparameter für den Prozess auf einer konkreten Maschine.</li>\n<li><code>Define Execution Dependencies</code>: Definiert modenabhängige Ausführungs- und Startreihenfolgen bzw. Abhängigkeiten zwischen Prozessen auf einer Maschine.</li>\n<li>Arbeits- und Konfigurationsartefakte:</li>\n<li><code>Executable Application</code> (Briefumschlag-Symbol mit Port-Leiste links): Ausführbares Software-Artefakt (Kardinalität <code>1</code> als Eingang).</li>\n<li><code>Process Design</code> (Dokument-Symbol): Entwurfsspezifikation des Prozesses (Kardinalität <code>1..*</code> als Eingang in <code>Associate Process with ProcessDesign</code>; assoziiert mit Kardinalität <code>1</code> zu <code>Process</code>).</li>\n<li><code>Process</code> (Dokument-Symbol): Instanziierter Prozess (Ausgang von <code>Define Process</code> mit <code>1..<em></code>; Ein- und Ausgang bei <code>Associate Process with ProcessDesign</code> jeweils mit <code>1..</em></code>; Eingang in Folgeaktivitäten mit <code>1</code>).</li>\n<li><code>Machine Manifest</code> (Briefumschlag-Symbol mit Port-Leiste links): Maschinenkonfiguration (Kardinalität <code>1</code> jeweils als Eingang für Folgeaktivitäten).</li>\n<li><code>Mode-dependent ...</code> (Dokument-Symbol): Modenabhängige Konfigurationen (Ausgang mit Kardinalität <code>1..*</code>).</li>\n<li>Beziehungen & Kanten:</li>\n<li>Stereotypisierte Datenflüsse («input», «output») mit Kardinalitäten.</li>\n<li>Gestrichelte Assoziationskante zwischen <code>Process</code> (Kardinalität <code>1..*</code>) und <code>Process Design</code> (Kardinalität <code>1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eine <code>Executable Application</code> wird als Eingang («input», 1) an <code>Define Process</code> übergeben, welche ein oder mehrere <code>Process</code>-Artefakte («output», 1..*) generiert.</li>\n<li>In der Aktivität <code>Associate Process with ProcessDesign</code> werden ein oder mehrere <code>Process</code>-Artefakte («input», 1..<em>) mit der Entwurfsspezifikation <code>Process Design</code> («input», 1..</em>) zusammengeführt; das aktualisierte Artefakt wird als <code>Process</code> («output», 1..<em>) fortgeführt, wodurch eine <code>1..</em></code> zu <code>1</code>-Zuordnung zwischen <code>Process</code> und <code>Process Design</code> etabliert wird.</li>\n<li>Der definierte <code>Process</code> («input», 1) wird zusammen mit dem <code>Machine Manifest</code> («input», 1) parallel an:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Define Startup Configuration</code> übergeben,</li>\n<li><code>Define Execution Dependencies</code> übergeben.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Beide Aktivitäten erzeugen modenabhängige Konfigurationselemente (<code>Mode-dependent ...</code>, «output», jeweils 1..*).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den AUTOSAR Adaptive Workflow: Die Konfiguration eines <code>Process</code> erfordert die formale Verknüpfung mit einem <code>Process Design</code>. Mehrere Prozesse können demselben <code>Process Design</code> zugeordnet sein (<code>1..*</code> zu <code>1</code>). Werkzeugketten müssen sicherstellen, dass die Zuordnung zwischen Design und Instanz vor oder während der Erstellung der Ausführungs- und Startkonfigurationen erfolgt.</p>"}, {"id": "FIG-1e7f6033efbc0fd4", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Ablaufdiagramm (SPEM/UML-Aktivitätsorientiert) zur Spezifikation und Konfiguration von Prozessen in der AUTOSAR Adaptive Platform. Das Diagramm modelliert den methodischen Workflow zur Überführung einer ausführbaren Anwendung (<code>Executable Application</code>) in instanziierte Prozesse (<code>Process</code>) sowie deren maschinenspezifische Start- und Ausführungsabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Aktivitäten (horizontale Prozesspfeile):</li>\n<li><code>Define Process</code>: Erzeugt Prozessinstanzen basierend auf der ausführbaren Anwendung.</li>\n<li><code>Associate Process with ProcessDesign</code>: Verknüpft die Prozessinstanz mit dem zugehörigen Entwurfsmodell (<code>Process Design</code>).</li>\n<li><code>Define Startup Configuration</code>: Definiert die zustands- und modenabhängigen Startparameter für den Prozess auf einer konkreten Maschine.</li>\n<li><code>Define Execution Dependencies</code>: Definiert modenabhängige Ausführungs- und Startreihenfolgen bzw. Abhängigkeiten zwischen Prozessen auf einer Maschine.</li>\n<li>Arbeits- und Konfigurationsartefakte:</li>\n<li><code>Executable Application</code> (Briefumschlag-Symbol mit Port-Leiste links): Ausführbares Software-Artefakt (Kardinalität <code>1</code> als Eingang).</li>\n<li><code>Process Design</code> (Dokument-Symbol): Entwurfsspezifikation des Prozesses (Kardinalität <code>1..*</code> als Eingang in <code>Associate Process with ProcessDesign</code>; assoziiert mit Kardinalität <code>1</code> zu <code>Process</code>).</li>\n<li><code>Process</code> (Dokument-Symbol): Instanziierter Prozess (Ausgang von <code>Define Process</code> mit <code>1..<em></code>; Ein- und Ausgang bei <code>Associate Process with ProcessDesign</code> jeweils mit <code>1..</em></code>; Eingang in Folgeaktivitäten mit <code>1</code>).</li>\n<li><code>Machine Manifest</code> (Briefumschlag-Symbol mit Port-Leiste links): Maschinenkonfiguration (Kardinalität <code>1</code> jeweils als Eingang für Folgeaktivitäten).</li>\n<li><code>Mode-dependent ...</code> (Dokument-Symbol): Modenabhängige Konfigurationen (Ausgang mit Kardinalität <code>1..*</code>).</li>\n<li>Beziehungen & Kanten:</li>\n<li>Stereotypisierte Datenflüsse («input», «output») mit Kardinalitäten.</li>\n<li>Gestrichelte Assoziationskante zwischen <code>Process</code> (Kardinalität <code>1..*</code>) und <code>Process Design</code> (Kardinalität <code>1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eine <code>Executable Application</code> wird als Eingang («input», 1) an <code>Define Process</code> übergeben, welche ein oder mehrere <code>Process</code>-Artefakte («output», 1..*) generiert.</li>\n<li>In der Aktivität <code>Associate Process with ProcessDesign</code> werden ein oder mehrere <code>Process</code>-Artefakte («input», 1..<em>) mit der Entwurfsspezifikation <code>Process Design</code> («input», 1..</em>) zusammengeführt; das aktualisierte Artefakt wird als <code>Process</code> («output», 1..<em>) fortgeführt, wodurch eine <code>1..</em></code> zu <code>1</code>-Zuordnung zwischen <code>Process</code> und <code>Process Design</code> etabliert wird.</li>\n<li>Der definierte <code>Process</code> («input», 1) wird zusammen mit dem <code>Machine Manifest</code> («input», 1) parallel an:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Define Startup Configuration</code> übergeben,</li>\n<li><code>Define Execution Dependencies</code> übergeben.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Beide Aktivitäten erzeugen modenabhängige Konfigurationselemente (<code>Mode-dependent ...</code>, «output», jeweils 1..*).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den AUTOSAR Adaptive Workflow: Die Konfiguration eines <code>Process</code> erfordert die formale Verknüpfung mit einem <code>Process Design</code>. Mehrere Prozesse können demselben <code>Process Design</code> zugeordnet sein (<code>1..*</code> zu <code>1</code>). Werkzeugketten müssen sicherstellen, dass die Zuordnung zwischen Design und Instanz vor oder während der Erstellung der Ausführungs- und Startkonfigurationen erfolgt.</p>"}, {"id": "FIG-045cebe68a862c07", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Ablaufdiagramm zur Spezifikation und Konfiguration von Prozessen in der AUTOSAR Adaptive Platform. Das Diagramm modelliert den methodischen Workflow zur Überführung eines ausführbaren Programms (<code>(Adaptive) Executable</code>) in instanziierte Prozesse (<code>Process</code>) sowie deren Verknüpfung mit dem Entwurf und den maschinenspezifischen Start- und Ausführungsabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Aktivitäten (horizontale Prozesspfeile):</li>\n<li><code>Define Process</code>: Erzeugt Prozessinstanzen basierend auf dem Executable.</li>\n<li><code>Associate Process with ProcessDesign</code>: Verknüpft die Prozessinstanz mit dem zugehörigen Entwurfsmodell (<code>Process Design</code>).</li>\n<li><code>Define Startup Configuration</code>: Definiert die zustands- und modenabhängigen Startparameter für den Prozess auf einer konkreten Maschine.</li>\n<li><code>Define Execution Dependencies</code>: Definiert modenabhängige Ausführungs- und Startreihenfolgen bzw. Abhängigkeiten zwischen Prozessen auf einer Maschine.</li>\n<li>Arbeits- und Konfigurationsartefakte:</li>\n<li><code>(Adaptive) Executable</code> (Briefumschlag-Symbol mit Port-Leiste links): Ausführbares Software-Artefakt (Kardinalität <code>1</code> als Eingang).</li>\n<li><code>Process Design</code> (Dokument-Symbol): Entwurfsspezifikation des Prozesses (Kardinalität <code>1..*</code> als Eingang in <code>Associate Process with ProcessDesign</code>; assoziiert mit Kardinalität <code>1</code> zu <code>Process</code>).</li>\n<li><code>Process</code> (Dokument-Symbol): Instanziierter Prozess (Ausgang von <code>Define Process</code> mit <code>1..<em></code>; Ein- und Ausgang bei <code>Associate Process with ProcessDesign</code> jeweils mit <code>1..</em></code> und <code>1</code>; Eingang in Folgeaktivitäten mit <code>1</code>).</li>\n<li><code>Machine Manifest</code> (Briefumschlag-Symbol mit Port-Leiste links): Maschinenkonfiguration (Kardinalität <code>1</code> jeweils als Eingang für Folgeaktivitäten).</li>\n<li><code>Mode-dependent ...</code> (Dokument-Symbol): Modenabhängige Konfigurationen (Ausgang mit Kardinalität <code>1..*</code>).</li>\n<li>Beziehungen & Kanten:</li>\n<li>Stereotypisierte Datenflüsse («input», «output») mit Kardinalitäten.</li>\n<li>Gestrichelte Assoziationskante zwischen <code>Process</code> (Kardinalität <code>1..*</code>) und <code>Process Design</code> (Kardinalität <code>1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ein <code>(Adaptive) Executable</code> wird als Eingang («input», 1) an <code>Define Process</code> übergeben, welche ein oder mehrere <code>Process</code>-Artefakte («output», 1..*) generiert.</li>\n<li>In der Aktivität <code>Associate Process with ProcessDesign</code> werden ein oder mehrere <code>Process</code>-Artefakte («input», 1..<em>) mit der Entwurfsspezifikation <code>Process Design</code> («input», 1..</em>) zusammengeführt; das aktualisierte Artefakt wird als <code>Process</code> («output», 1..<em>) fortgeführt, wodurch eine <code>1..</em></code> zu <code>1</code>-Zuordnung zwischen <code>Process</code> und <code>Process Design</code> etabliert wird.</li>\n<li>Der definierte <code>Process</code> («input», 1) wird zusammen mit dem <code>Machine Manifest</code> («input», 1) parallel an:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Define Startup Configuration</code> übergeben,</li>\n<li><code>Define Execution Dependencies</code> übergeben.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Beide Aktivitäten erzeugen modenabhängige Konfigurationselemente (<code>Mode-dependent ...</code>, «output», jeweils 1..*).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den AUTOSAR Adaptive Workflow: Die Konfiguration eines <code>Process</code> basiert auf einem <code>(Adaptive) Executable</code> und erfordert die formale Verknüpfung mit einem <code>Process Design</code>. Mehrere Prozesse können demselben <code>Process Design</code> zugeordnet sein (<code>1..*</code> zu <code>1</code>). Werkzeugketten müssen sicherstellen, dass die Zuordnung zwischen Design und Instanz vor oder während der Erstellung der maschinenspezifischen Ausführungs- und Startkonfigurationen erfolgt.</p>"}, {"id": "FIG-b4046f320f337be7", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Ablaufdiagramm zur Spezifikation und Konfiguration von Prozessen in der AUTOSAR Adaptive Platform. Das Diagramm modelliert den methodischen Workflow zur Überführung eines ausführbaren Programms (<code>(Adaptive) Executable</code>) in instanziierte Prozesse (<code>Process</code>) sowie deren Verknüpfung mit dem Entwurf und den maschinenspezifischen Start- und Ausführungsabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Aktivitäten (horizontale Prozesspfeile):</li>\n<li><code>Define Process</code>: Erzeugt Prozessinstanzen basierend auf dem Executable.</li>\n<li><code>Associate Process with ProcessDesign</code>: Verknüpft die Prozessinstanz mit dem zugehörigen Entwurfsmodell (<code>Process Design</code>).</li>\n<li><code>Define Startup Configuration</code>: Definiert die zustands- und modenabhängigen Startparameter für den Prozess auf einer konkreten Maschine.</li>\n<li><code>Define Execution Dependencies</code>: Definiert modenabhängige Ausführungs- und Startreihenfolgen bzw. Abhängigkeiten zwischen Prozessen auf einer Maschine.</li>\n<li>Arbeits- und Konfigurationsartefakte:</li>\n<li><code>(Adaptive) Executable</code> (Briefumschlag-Symbol mit Port-Leiste links): Ausführbares Software-Artefakt (Kardinalität <code>1</code> als Eingang).</li>\n<li><code>Process Design</code> (Dokument-Symbol): Entwurfsspezifikation des Prozesses (Kardinalität <code>1..*</code> als Eingang in <code>Associate Process with ProcessDesign</code>; assoziiert mit Kardinalität <code>1</code> zu <code>Process</code>).</li>\n<li><code>Process</code> (Dokument-Symbol): Instanziierter Prozess (Ausgang von <code>Define Process</code> mit <code>1..<em></code>; Ein- und Ausgang bei <code>Associate Process with ProcessDesign</code> jeweils mit <code>1..</em></code> und <code>1</code>; Eingang in Folgeaktivitäten mit <code>1</code>).</li>\n<li><code>Machine Manifest</code> (Briefumschlag-Symbol mit Port-Leiste links): Maschinenkonfiguration (Kardinalität <code>1</code> jeweils als Eingang für Folgeaktivitäten).</li>\n<li><code>Mode-dependent ...</code> (Dokument-Symbol): Modenabhängige Konfigurationen (Ausgang mit Kardinalität <code>1..*</code>).</li>\n<li>Beziehungen & Kanten:</li>\n<li>Stereotypisierte Datenflüsse («input», «output») mit Kardinalitäten.</li>\n<li>Gestrichelte Assoziationskante zwischen <code>Process</code> (Kardinalität <code>1..*</code>) und <code>Process Design</code> (Kardinalität <code>1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ein <code>(Adaptive) Executable</code> wird als Eingang («input», 1) an <code>Define Process</code> übergeben, welche ein oder mehrere <code>Process</code>-Artefakte («output», 1..*) generiert.</li>\n<li>In der Aktivität <code>Associate Process with ProcessDesign</code> werden ein oder mehrere <code>Process</code>-Artefakte («input», 1..<em>) mit der Entwurfsspezifikation <code>Process Design</code> («input», 1..</em>) zusammengeführt; das aktualisierte Artefakt wird als <code>Process</code> («output», 1..<em>) fortgeführt, wodurch eine <code>1..</em></code> zu <code>1</code>-Zuordnung zwischen <code>Process</code> und <code>Process Design</code> etabliert wird.</li>\n<li>Der definierte <code>Process</code> («input», 1) wird zusammen mit dem <code>Machine Manifest</code> («input», 1) parallel an:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Define Startup Configuration</code> übergeben,</li>\n<li><code>Define Execution Dependencies</code> übergeben.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Beide Aktivitäten erzeugen modenabhängige Konfigurationselemente (<code>Mode-dependent ...</code>, «output», jeweils 1..*).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den AUTOSAR Adaptive Workflow: Die Konfiguration eines <code>Process</code> basiert auf einem <code>(Adaptive) Executable</code> und erfordert die formale Verknüpfung mit einem <code>Process Design</code>. Mehrere Prozesse können demselben <code>Process Design</code> zugeordnet sein (<code>1..*</code> zu <code>1</code>). Werkzeugketten müssen sicherstellen, dass die Zuordnung zwischen Design und Instanz vor oder während der Erstellung der maschinenspezifischen Ausführungs- und Startkonfigurationen erfolgt.</p>"}], "trans": [{"from": "FIG-2dbe784b7eb59f49", "to": "FIG-4747b509285e17c5", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung der Aktivität <code>Associate Process with ProcessDesign</code> mit Eingängen von <code>Process Design</code> (Kardinalität <code>1..<em></code>) und <code>Process</code> (Kardinalität <code>1..</em></code>) sowie Ausgang zu <code>Process</code> (Kardinalität <code>1..*</code>).</li>\n<li>Ergänzung des Artefakts <code>Process Design</code>.</li>\n<li>Ergänzung einer gestrichelten Assoziationslinie zwischen <code>Process</code> (Kardinalität <code>1..*</code>) und <code>Process Design</code> (Kardinalität <code>1</code>).</li>\n</ul>"}, {"from": "FIG-4747b509285e17c5", "to": "FIG-1e7f6033efbc0fd4", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Umstellung des Layouts von vertikalem zu horizontal-versetztem Fluss: <code>Executable Application</code> befindet sich nun oben links mit horizontalem Pfeil auf <code>Define Process</code>.</li>\n<li>Die Beschriftungen <code>Define Process</code> und <code>Process Design</code> sind nun oberhalb der jeweiligen Symbole platziert.</li>\n<li>Bei der Assoziationslinie und den Pfeilen zwischen <code>Process</code> und <code>Associate Process with ProcessDesign</code> wurden zusätzliche Kardinalitätsangaben <code>1</code> an den Verbindungspunkten visualisiert.</li>\n</ul>"}, {"from": "FIG-1e7f6033efbc0fd4", "to": "FIG-045cebe68a862c07", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Umbenennung des Eingangs-Artefakts von <code>Executable Application</code> zu <code>(Adaptive) Executable</code>.</li>\n</ul>"}, {"from": "FIG-045cebe68a862c07", "to": "FIG-b4046f320f337be7", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
